// Bronwyn's letterheads, taken from her 2026 Word masters
// (_contract_templates/2026-final/*.docx), so logo, strapline, "Initial here"
// box, address and directors line are exactly hers.
//
//   properties — DREAM PROPERTIES logo: the freehold-house and land agreements,
//                movables agreement and addenda.
//   knysna     — DREAM KNYSNA logo (as in "Dream Properties Letterhead & Page
//                Numbers.docx"): the sectional-title agreement.
//   mandate    — as properties, but pages after the first carry only the rule
//                and directors line (no "Initial here"), as in the mandates.
//   open       — as mandate, but the open mandate's first page has no
//                "Initial here" box (address and directors only), so its
//                body runs lower.
//   appendix   — no header at all; "Initial here" and directors line only
//                (the condition-report appendix).
//
// Each image is a full-page-width strip (A4, 595.28 pt) cut from a 300 dpi
// render of the master; `top`/`bottom` place it exactly where Word puts it.
// "First" is page 1 (Word's different-first-page header/footer).
// Generated — do not edit by hand.

export type LetterheadPart = { src: string; top: number; bottom: number } | null;
export type Letterhead = { headerFirst: LetterheadPart; header: LetterheadPart; footerFirst: LetterheadPart; footer: LetterheadPart };

